class Parent {
    private void display() {
        System.out.println("Parent");
    }
    public void show() {
        display();
    }
}

class Child extends Parent {
    public void display() {
        System.out.println("Child");
    }
}

public class Test {
    public static void main(String[] args) {
        Parent p = new Child();
        p.show();
    }
}
